package com.hbm.satellite.control.client;
import com.hbm.client.gui.LegacyScreen;import com.hbm.client.gui.font.LegacyFonts;import com.hbm.machine.storage.CrateStackData;import com.hbm.satellite.control.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.InteractionHand;import net.neoforged.neoforge.network.PacketDistributor;import org.apache.commons.lang3.math.NumberUtils;
/** Original176x126 coordinate terminal, original field limits/pixels/conditional Y and source connection LEDs. */
public final class SatelliteCoordinateScreen extends LegacyScreen {
 private static final ResourceLocation TEXTURE=ResourceLocation.parse("hbm:textures/gui/satellites/gui_sat_coord.png");private final InteractionHand hand;private int left,top;private EditBox xField,yField,zField;
 public SatelliteCoordinateScreen(InteractionHand hand){super(Component.translatable("item.hbm.sat_coord"));this.hand=hand;}
 @Override protected void init(){font=LegacyFonts.get();left=(width-176)/2;top=(height-126)/2;xField=field(left+66,top+21,"X");yField=field(left+66,top+56,"Y");zField=field(left+66,top+92,"Z");}
 private EditBox field(int x,int y,String name){var field=new EditBox(font,x,y,48,12,Component.literal(name));field.setTextColor(-1);field.setTextColorUneditable(-1);field.setBordered(false);field.setMaxLength(7);return addRenderableWidget(field);}
 private boolean connected(){return minecraft.player!=null&&minecraft.player.getItemInHand(hand).getItem() instanceof SatelliteCoordinateItem&&CrateStackData.data(minecraft.player.getItemInHand(hand)).getBoolean(SatelliteCoordinateItem.KEY_NBT_CONNECTED);}
 @Override public boolean mouseClicked(double x,double y,int button){if(!connected())return false;boolean handled=super.mouseClicked(x,y,button);if(x>=left+133&&x<left+151&&y>=top+52&&y<top+70&&minecraft.player!=null){if(NumberUtils.isNumber(xField.getValue())&&NumberUtils.isNumber(zField.getValue())){try{int tx=(int)Double.parseDouble(xField.getValue()),tz=(int)Double.parseDouble(zField.getValue());Integer ty=NumberUtils.isNumber(yField.getValue())?(int)Double.parseDouble(yField.getValue()):null;minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1F));PacketDistributor.sendToServer(new SatelliteCoordinateControl(hand,tx,ty,tz));minecraft.setScreen(null);return true;}catch(NumberFormatException ignored){}}}return handled;}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if(xField.keyPressed(key,scan,modifiers)||yField.keyPressed(key,scan,modifiers)||zField.keyPressed(key,scan,modifiers))return true;return super.keyPressed(key,scan,modifiers);}
 @Override public boolean charTyped(char letter,int modifiers){return xField.charTyped(letter,modifiers)||yField.charTyped(letter,modifiers)||zField.charTyped(letter,modifiers)||super.charTyped(letter,modifiers);}
 @Override public void render(GuiGraphics graphics,int mx,int my,float partial){renderBackground(graphics,mx,my,partial);graphics.setColor(1,1,1,1);graphics.blit(TEXTURE,left,top,0,0,176,126);if(xField.isFocused())graphics.blit(TEXTURE,left+61,top+16,0,126,54,18);if(yField.isFocused())graphics.blit(TEXTURE,left+61,top+52,0,126,54,18);if(zField.isFocused())graphics.blit(TEXTURE,left+61,top+88,0,126,54,18);if(connected()){graphics.blit(TEXTURE,left+120,top+17,194,0,7,7);graphics.blit(TEXTURE,left+120,top+25,194,0,7,7);}super.render(graphics,mx,my,partial);}
 @Override public boolean isPauseScreen(){return false;}
}
